package net.civeira.phylax.features.access.tenantconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class MagicLinkEnabledVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property magic link enabled of tenant config ")
  void test_magic_link_enabled_v_o_builder() {
    Assertions.assertFalse(MagicLinkEnabledVO.nullValue().isMagicLinkEnabled(),
        "A empty vo should have a null value");
    Assertions.assertFalse(MagicLinkEnabledVO.tryFrom(null).isMagicLinkEnabled(),
        "With a null value, no present result");
    Assertions.assertEquals(true, MagicLinkEnabledVO.from(true).isMagicLinkEnabled());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> MagicLinkEnabledVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", MagicLinkEnabledVO.from(true).toString());
  }
}
